'use strict';

/**
* Maximum safe nth Tribonacci number when stored in half-precision floating-point format.
*
* @module @stdlib/constants/float16/max-safe-nth-tribonacci
* @type {integer}
*
* @example
* var FLOAT16_MAX_SAFE_NTH_TRIBONACCI = require( '@stdlib/constants/float16/max-safe-nth-tribonacci' );
* // returns 15
*/


// MAIN //

/**
* Maximum safe nth Tribonacci number when stored in half-precision floating-point format.
*
* @constant
* @type {integer}
* @default 15
* @see [Tribonacci number]{@link https://en.wikipedia.org/wiki/Tribonacci_number}
* @see [Half-precision floating-point format]{@link https://en.wikipedia.org/wiki/Half-precision_floating-point_format}
*/
var FLOAT16_MAX_SAFE_NTH_TRIBONACCI = 15|0; // eslint-disable-line id-length


// EXPORTS //

module.exports = FLOAT16_MAX_SAFE_NTH_TRIBONACCI;
